-- ************************************** GOLD.PIPELINE_BY_STAGE_SEGMENT_REGION
CREATE VIEW GOLD.PIPELINE_BY_STAGE_SEGMENT_REGION
(
  STAGE_NAME COMMENT 'Opportunity stage.',
  SEGMENT COMMENT 'Account type used as segment.',
  REGION COMMENT 'Account billing country used as region.',
  OPPORTUNITY_COUNT COMMENT 'Number of open opportunities.',
  OPEN_AMOUNT COMMENT 'Sum of opportunity amounts.',
  WEIGHTED_AMOUNT COMMENT 'Sum of amount multiplied by probability.'
)
COMMENT = 'Open pipeline by stage, segment (account type) and region (billing country). Excludes deleted and closed opportunities. Weighted amount = amount x probability.'
AS
select coalesce(o.STAGE_NAME, 'Unknown') as STAGE_NAME, coalesce(a.TYPE, 'Unknown') as SEGMENT, coalesce(a.BILLING_COUNTRY, 'Unknown') as REGION, count(*) as OPPORTUNITY_COUNT, sum(o.AMOUNT) as OPEN_AMOUNT, sum(o.AMOUNT * o.PROBABILITY / 100) as WEIGHTED_AMOUNT from SILVER.OPPORTUNITY o left join SILVER.ACCOUNT a on o.ACCOUNT_ID = a.ID where o.IS_CLOSED = false and o.IS_DELETED = false group by 1, 2, 3;

